    {
        "id": "checkSuccess",
        "type": "core.logic.decision",
        "typeVersion": "1.1",
        "display": {"label": "Call Succeeded?"},
        "inputs": {
            "expression": "$vars.addActivityAct3651.output != null",
            "trueLabel": "Success",
            "falseLabel": "Failure"
        }
