    {
        "id": "terminateNode",
        "type": "core.logic.terminate",
        "typeVersion": "1.0",
        "display": {"label": "Terminate - Failed"},
        "inputs": {
            "errorMessage": "ComplexArray test failed"
        }
    },
    {
        "id": "logPassed",
        "type": "core.action.script",
        "typeVersion": "1.0",
        "display": {"label": "Log - Passed"},
        "inputs": {
            "script": "return { message: 'ComplexArray test passed' };"
        }
    },
    {
        "id": "end",
        "type": "core.control.end",
        "typeVersion": "1.0",
        "display": {"label": "End"}
    }
]

flow['nodes'].extend(new_nodes)

# Add edges
new_edges = [
    {"id": "e1", "sourceNodeId": "start", "sourcePort": "output", "targetNodeId": "addActivityAct3651", "targetPort": "input"},
    {"id": "e2", "sourceNodeId": "addActivityAct3651", "sourcePort": "output", "targetNodeId": "checkSuccess", "targetPort": "input"},
    {"id": "e3", "sourceNodeId": "addActivityAct3651", "sourcePort": "error", "targetNodeId": "terminateNode", "targetPort": "input"},
