    {"id": "e5", "sourceNodeId": "checkSuccess", "sourcePort": "false", "targetNodeId": "terminateNode", "targetPort": "input"},
    {"id": "e6", "sourceNodeId": "logPassed", "sourcePort": "success", "targetNodeId": "end", "targetPort": "input"}
]
flow['edges'] = new_edges

# Add definitions for OOTB nodes
flow['definitions'].extend([decision_def, terminate_def, script_def, end_def])

# Add variables.nodes entries for user-owned data-producing nodes (logPassed script outputs)
flow['variables']['nodes'].append({
